using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using backend.Models;

namespace backend.Controllers
{
    /// <summary>
    /// One-time data seeding endpoint.
    /// Seeds qualifications and unit standards into the Railway database.
    /// </summary>
    [ApiController]
    [Route("api/[controller]")]
    public class SeedController : ControllerBase
    {
        private readonly ApplicationDbContext _context;
        private readonly ILogger<SeedController> _logger;

        public SeedController(ApplicationDbContext context, ILogger<SeedController> logger)
        {
            _context = context;
            _logger = logger;
        }

        /// <summary>
        /// GET /api/seed/status — check how many records exist
        /// </summary>
        [HttpGet("status")]
        public async Task<IActionResult> Status()
        {
            var legacyQuals = await _context.LegacyQualifications.CountAsync();
            var legacyUS    = await _context.LegacyUnitStandards.CountAsync();
            var occQuals    = await _context.OccupationalQualifications.CountAsync();
            var occUS       = await _context.OccupationalUnitStandards.CountAsync();

            return Ok(new
            {
                legacyQualifications       = legacyQuals,
                legacyUnitStandards        = legacyUS,
                occupationalQualifications = occQuals,
                occupationalUnitStandards  = occUS,
                needsSeeding               = legacyQuals < 100,
                needsOccSeeding            = occQuals < 100
            });
        }

        /// <summary>
        /// POST /api/seed/migrate — applies pending schema migrations (idempotent).
        /// </summary>
        [HttpPost("migrate")]
        public async Task<IActionResult> Migrate()
        {
            var results = new List<string>();
            try
            {
                await _context.Database.ExecuteSqlRawAsync(
                    @"ALTER TABLE ""SkillsDevelopmentProviders"" ADD COLUMN IF NOT EXISTS ""LogoPath"" VARCHAR(500) NULL;");
                results.Add("SkillsDevelopmentProviders.LogoPath: OK");
            }
            catch (Exception ex) { results.Add($"LogoPath: SKIPPED ({ex.Message})"); }

            return Ok(new { success = true, migrations = results });
        }

        /// <summary>
        /// POST /api/seed/occupational — seeds occupational qualifications and unit standards.
        /// Executes pre-generated PostgreSQL INSERT ... ON CONFLICT DO NOTHING statements.
        /// Safe to run multiple times.
        /// </summary>
        [HttpPost("occupational")]
        public async Task<IActionResult> SeedOccupational()
        {
            try
            {
                _logger.LogInformation("Starting occupational qualification seeding...");

                var occQualsBefore = await _context.OccupationalQualifications.CountAsync();
                var occUSBefore    = await _context.OccupationalUnitStandards.CountAsync();

                // ── Occupational Qualifications (859 records) ────────────────────
                var qualsSql = GetOccupationalQualificationsSql();
                var qualStatements = qualsSql
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries)
                    .Where(s => s.TrimStart().StartsWith("INSERT"))
                    .ToList();

                int qualsAdded = 0;
                foreach (var sql in qualStatements)
                {
                    try
                    {
                        var rows = await _context.Database.ExecuteSqlRawAsync(sql);
                        qualsAdded += rows;
                    }
                    catch (Exception ex)
                    {
                        _logger.LogWarning("Skipped qual row: {Error}", ex.Message);
                    }
                }
                _logger.LogInformation("Seeded {Count} occupational qualifications", qualsAdded);

                // ── Occupational Unit Standards (986 records) ────────────────────
                var usSql = GetOccupationalUnitStandardsSql();
                var usStatements = usSql
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries)
                    .Where(s => s.TrimStart().StartsWith("INSERT"))
                    .ToList();

                int usAdded = 0;
                foreach (var sql in usStatements)
                {
                    try
                    {
                        var rows = await _context.Database.ExecuteSqlRawAsync(sql);
                        usAdded += rows;
                    }
                    catch (Exception ex)
                    {
                        _logger.LogWarning("Skipped US row: {Error}", ex.Message);
                    }
                }
                _logger.LogInformation("Seeded {Count} occupational unit standards", usAdded);

                var occQualsAfter = await _context.OccupationalQualifications.CountAsync();
                var occUSAfter    = await _context.OccupationalUnitStandards.CountAsync();

                return Ok(new
                {
                    success = true,
                    message = "Occupational seeding complete",
                    occupationalQualifications = new
                    {
                        before = occQualsBefore,
                        after  = occQualsAfter,
                        added  = qualsAdded,
                        total  = qualStatements.Count
                    },
                    occupationalUnitStandards = new
                    {
                        before = occUSBefore,
                        after  = occUSAfter,
                        added  = usAdded,
                        total  = usStatements.Count
                    }
                });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Occupational seeding failed");
                return StatusCode(500, new { success = false, message = ex.Message, detail = ex.InnerException?.Message });
            }
        }

        /// <summary>
        /// POST /api/seed/qualifications — seeds all qualification and unit standard data.
        /// Safe to run multiple times (uses INSERT ... ON CONFLICT DO NOTHING).
        /// </summary>
        [HttpPost("qualifications")]
        public async Task<IActionResult> SeedQualifications()
        {
            try
            {
                _logger.LogInformation("Starting qualification seeding...");

                var legacyQualsBefore = await _context.LegacyQualifications.CountAsync();
                var legacyUSBefore    = await _context.LegacyUnitStandards.CountAsync();

                // ── Legacy Qualifications ────────────────────────────────────────
                var legacyQuals = GetLegacyQualifications();
                int qualsAdded = 0;
                foreach (var q in legacyQuals)
                {
                    if (!await _context.LegacyQualifications.AnyAsync(x => x.Id == q.Id))
                    {
                        _context.LegacyQualifications.Add(q);
                        qualsAdded++;
                    }
                }
                await _context.SaveChangesAsync();
                _logger.LogInformation("Added {Count} legacy qualifications", qualsAdded);

                // ── Legacy Unit Standards ────────────────────────────────────────
                var legacyUS = GetLegacyUnitStandards();
                int usAdded = 0;
                const int batchSize = 500;
                var usBatches = legacyUS.Chunk(batchSize);
                foreach (var batch in usBatches)
                {
                    foreach (var us in batch)
                    {
                        if (!await _context.LegacyUnitStandards.AnyAsync(x => x.Id == us.Id))
                        {
                            _context.LegacyUnitStandards.Add(us);
                            usAdded++;
                        }
                    }
                    await _context.SaveChangesAsync();
                    _logger.LogInformation("Seeded batch, total so far: {Count}", usAdded);
                }

                var legacyQualsAfter = await _context.LegacyQualifications.CountAsync();
                var legacyUSAfter    = await _context.LegacyUnitStandards.CountAsync();

                return Ok(new
                {
                    success = true,
                    message = "Seeding complete",
                    legacyQualifications = new { before = legacyQualsBefore, after = legacyQualsAfter, added = qualsAdded },
                    legacyUnitStandards  = new { before = legacyUSBefore,    after = legacyUSAfter,    added = usAdded }
                });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Seeding failed");
                return StatusCode(500, new { success = false, message = ex.Message });
            }
        }

