        // ── Occupational SQL data ────────────────────────────────────────────────

        private static string GetOccupationalQualificationsSql()
        {
            // 859 occupational qualifications from local database
            // PostgreSQL INSERT ... ON CONFLICT DO NOTHING — safe to re-run
            var sb = new System.Text.StringBuilder();
            foreach (var row in OccQualRows)
                sb.AppendLine($"INSERT INTO occupational_qualifications (qualification_id, name, level, credits, qualification_type, description, quality_partner, trade, has_cat) VALUES {row} ON CONFLICT (qualification_id) DO NOTHING;");
            return sb.ToString();
        }

        private static string GetOccupationalUnitStandardsSql()
        {
            // 986 occupational unit standards from local database
            var sb = new System.Text.StringBuilder();
            foreach (var row in OccUSRows)
                sb.AppendLine($"INSERT INTO occupational_unit_standards (id, qualification_id, module_code, unit_standard_name, module_type, level, credits) VALUES {row} ON CONFLICT (id) DO NOTHING;");
            return sb.ToString();
        }

